def articulationPoints(V, adj):
    from collections import defaultdict

    disc = [-1] * V
    low = [-1] * V
    visited = [False] * V
    is_articulation = [False] * V
    time = 0
    children = defaultdict(int)

    def dfs(u, parent):
        nonlocal time
        children[u] = 0
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                children[u] += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])

                if parent == -1 and children[u] > 1:
                    is_articulation[u] = True
                if parent != -1 and low[v] >= disc[u]:
                    is_articulation[u] = True
